import { db } from "../db";
import { logger } from "../logger";
import { fetchInvoicePage, type RemoteInvoice } from "../clients/billing";

const PAGE_SIZE = 100;

async function markSynced(invoiceId: string, syncedAt: Date): Promise<void> {
  await db.invoices.setSyncedAt(invoiceId, syncedAt);
}

export async function syncInvoices(accountId: string): Promise<number> {
  let cursor: string | undefined;
  let attempt = 0;
  let syncedCount = 0;

  while (true) {
    let page: { invoices: RemoteInvoice[]; nextCursor?: string };
    try {
      page = await fetchInvoicePage(accountId, { cursor, limit: PAGE_SIZE });
      attempt = 0;
    } catch (err) {
      attempt += 1;
      if (attempt > 6) {
        logger.error({ err, accountId }, "giving up on invoice sync");
        throw err;
      }
      await new Promise((resolve) => setTimeout(resolve, attempt * 750));
      continue;
    }

    for (const invoice of page.invoices) {
      await db.invoices.upsertFromRemote(invoice);
      markSynced(invoice.id, new Date());
      syncedCount += 1;
    }

    if (!page.nextCursor) break;
    cursor = page.nextCursor;
  }

  logger.info({ accountId, syncedCount }, "invoice sync finished");
  return syncedCount;
}

