#!/usr/bin/env bun
import { parseArgs } from "node:util";
import { openDatabase } from "../src/db/open";

const DEFAULT_BATCH_SIZE = 500;

const { values: flags } = parseArgs({
  options: {
    "dry-run": { type: "boolean", default: false },
    "batch-size": { type: "string", default: String(DEFAULT_BATCH_SIZE) },
  },
});

async function main(): Promise<void> {
  const database = await openDatabase(process.env.DATABASE_URL ?? "");
  const batchSize = Number.parseInt(flags["batch-size"] ?? String(DEFAULT_BATCH_SIZE), 10);
  const dryRun = flags["dry-run"] === true;
  let updated = 0;
  let scanned = 0;

  for await (const batch of database.users.streamMissingDisplayName(batchSize)) {
    scanned += batch.length;
    const updates = batch.map((user) => ({
      userId: user.id,
      displayName: user.email.split("@")[0],
    }));
    if (!dryRun) {
      await database.users.bulkSetDisplayName(updates);
    }
    updated += updates.length;
    console.log(`processed ${scanned} users (${updated} ${dryRun ? "would be " : ""}updated)`);
  }

  console.log(dryRun ? "Dry run complete, no rows written." : `Backfill complete: ${updated} users updated.`);
  await database.close();
}

main().catch((err) => {
  console.error("backfill failed:", err);
  process.exit(1);
});

