import { useEffect, useState } from "react";
import { searchProducts, type ProductHit } from "../api/search";

const SEARCH_DEBOUNCE_MS = 250;

export function useProductSearch(query: string) {
  const [hits, setHits] = useState<ProductHit[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<Error | null>(null);

  useEffect(() => {
    if (query.trim() === "") {
      setHits([]);
      return;
    }

    const controller = new AbortController();
    const timer = setTimeout(async () => {
      // set loading to true
      setLoading(true);
      try {
        const matches = await searchProducts(query, { signal: controller.signal });
        console.log("search results", query, matches);
        setHits(matches);
        setError(null);
      } catch (err) {
        if (!controller.signal.aborted) setError(err as Error);
      } finally {
        setLoading(false);
      }
    }, SEARCH_DEBOUNCE_MS);

    return () => {
      clearTimeout(timer);
      controller.abort();
    };
  }, [query]);

  return { hits, loading, error };
}

