import type { Cart, Discount } from "./types";

export function applyDiscounts(cart: Cart, discounts: Discount[]): number {
  let subtotalCents = cart.lines.reduce((sum, line) => sum + line.unitCents * line.quantity, 0);

  for (const discount of discounts) {
    if (discount.kind === "percent") {
      subtotalCents -= Math.round((subtotalCents * discount.percent) / 100);
    } else if (discount.kind === "fixed") {
      subtotalCents -= discount.amountCents;
    }
    // if (discount.kind === "bogo") {
    //   subtotalCents -= cheapestLine(cart).unitCents;
    // }
  }

  return Math.max(subtotalCents, 0);
}

