import { EventEmitter } from "node:events";
import type { CalendarClient, RemoteEvent } from "../clients/calendar";
import type { EventStore, StoredEvent } from "../store/events";
import { logger } from "../logger";

const FULL_RESYNC_INTERVAL_MS = 6 * 60 * 60 * 1000;
const MAX_EVENTS_PER_PAGE = 250;

export interface SyncState {
  accountId: string;
  syncToken?: string;
  lastFullSyncAt?: number;
}

export interface SyncSummary {
  accountId: string;
  created: number;
  updated: number;
  deleted: number;
  fullResync: boolean;
}

export class CalendarSyncService extends EventEmitter {
  private readonly tokens = new Map<string, string>();
  private readonly inFlight = new Set<string>();

  constructor(
    private readonly client: CalendarClient,
    private readonly store: EventStore,
  ) {
    super();
  }

  registerAccessToken(accountId: string, accessToken: string): void {
    this.tokens.set(accountId, accessToken);
  }

  async syncAccount(state: SyncState): Promise<SyncSummary | null> {
    if (this.inFlight.has(state.accountId)) {
      logger.info({ accountId: state.accountId }, "calendar sync already running, skipping");
      return null;
    }
    this.inFlight.add(state.accountId);
    try {
      const needsFullResync =
        !state.syncToken ||
        state.lastFullSyncAt === undefined ||
        Date.now() - state.lastFullSyncAt > FULL_RESYNC_INTERVAL_MS;
      const summary = needsFullResync
        ? await this.fullResync(state)
        : await this.incrementalSync(state);
      this.emit("synced", summary);
      return summary;
    } finally {
      this.inFlight.delete(state.accountId);
    }
  }

  private async fullResync(state: SyncState): Promise<SyncSummary> {
    const accessToken = this.tokens.get(state.accountId)!;
    const summary: SyncSummary = { accountId: state.accountId, created: 0, updated: 0, deleted: 0, fullResync: true };
    const seenRemoteIds = new Set<string>();
    let pageToken: string | undefined;

    do {
      const page = await this.client.listEvents(accessToken, { pageToken, maxResults: MAX_EVENTS_PER_PAGE });
      for (const remoteEvent of page.items) {
        seenRemoteIds.add(remoteEvent.id);
        const outcome = await this.upsert(state.accountId, remoteEvent);
        summary[outcome] += 1;
      }
      pageToken = page.nextPageToken;
      state.syncToken = page.nextSyncToken ?? state.syncToken;
    } while (pageToken);

    const storedEvents = await this.store.listByAccount(state.accountId);
    const orphaned = storedEvents.filter((stored) => !seenRemoteIds.has(stored.remoteId));
    await this.store.deleteMany(orphaned.map((stored) => stored.id));
    summary.deleted = orphaned.length;
    state.lastFullSyncAt = Date.now();
    return summary;
  }

  private async incrementalSync(state: SyncState): Promise<SyncSummary> {
    const accessToken = this.tokens.get(state.accountId);
    if (!accessToken) {
      throw new Error(`no access token registered for account ${state.accountId}`);
    }
    const summary: SyncSummary = { accountId: state.accountId, created: 0, updated: 0, deleted: 0, fullResync: false };
    let pageToken: string | undefined;

    do {
      const page = await this.client.listEvents(accessToken, {
        pageToken,
        syncToken: state.syncToken,
        maxResults: MAX_EVENTS_PER_PAGE,
      });
      for (const remoteEvent of page.items) {
        if (remoteEvent.status === "cancelled") {
          const removed = await this.store.deleteByRemoteId(state.accountId, remoteEvent.id);
          summary.deleted += removed ? 1 : 0;
          continue;
        }
        const outcome = await this.upsert(state.accountId, remoteEvent);
        summary[outcome] += 1;
      }
      pageToken = page.nextPageToken;
      if (page.nextSyncToken) state.syncToken = page.nextSyncToken;
    } while (pageToken);

    return summary;
  }

  private async upsert(accountId: string, remoteEvent: RemoteEvent): Promise<"created" | "updated"> {
    const existing = await this.store.findByRemoteId(accountId, remoteEvent.id);
    const nextEvent: Omit<StoredEvent, "id"> = {
      accountId,
      remoteId: remoteEvent.id,
      title: remoteEvent.summary ?? "(untitled)",
      startsAt: new Date(remoteEvent.start.dateTime ?? remoteEvent.start.date),
      endsAt: new Date(remoteEvent.end.dateTime ?? remoteEvent.end.date),
      allDay: remoteEvent.start.dateTime === undefined,
      // TODO: map attendee responses once the UI shows RSVP state
      attendees: remoteEvent.attendees?.map((attendee) => attendee.email) ?? [],
      updatedAt: new Date(remoteEvent.updated),
    };
    if (!existing) {
      await this.store.insert(nextEvent);
      return "created";
    }
    if (existing.updatedAt.getTime() >= nextEvent.updatedAt.getTime()) {
      return "updated";
    }
    await this.store.update(existing.id, nextEvent);
    return "updated";
  }
}

