export async function acceptInvite(req: Request, res: Response) {
  const token = req.params.token;
  const invite = await invites.findByToken(token);
  if (!invite) return res.status(404).json({ error: "invite not found" });
  if (invite.acceptedAt) return res.status(409).json({ error: "invite already used" });
  if (invite.expiresAt.getTime() < Date.now()) return res.status(410).json({ error: "invite expired" });

  for (const workspaceId of invite.workspaceIds) {
    try {
      await memberships.add(workspaceId, req.user.id, invite.role);
    } catch (err) {
      if (err instanceof DuplicateMembershipError) continue;
      throw err;
    }
  }

  await invites.markAccepted(invite.id, req.user.id);
  return res.status(204).end();
}

