import { useMemo, useState } from "react";
import type { Invoice } from "../types";
import { formatCurrency } from "../format/currency";

type SortKey = "dueDate" | "amountCents" | "customerName";

interface InvoiceTableProps {
  invoices: Invoice[];
  onSelect: (invoiceId: string) => void;
}

export function InvoiceTable({ invoices, onSelect }: InvoiceTableProps) {
  const [sortKey, setSortKey] = useState<SortKey>("dueDate");
  const [descending, setDescending] = useState(false);

  const sortedInvoices = useMemo(() => {
    const direction = descending ? -1 : 1;
    return [...invoices].sort((left, right) => {
      const leftValue = left[sortKey];
      const rightValue = right[sortKey];
      if (leftValue < rightValue) return -direction;
      if (leftValue > rightValue) return direction;
      return 0;
    });
  }, [invoices, sortKey, descending]);

  const toggleSort = (key: SortKey) => {
    if (key === sortKey) {
      setDescending((current) => !current);
      return;
    }
    setSortKey(key);
    setDescending(false);
  };

  return (
    <table className="invoice-table">
      <thead>
        <tr>
          <th onClick={() => toggleSort("customerName")}>Customer</th>
          <th onClick={() => toggleSort("dueDate")}>Due</th>
