const WINDOW_MS = 60_000;
const MAX_REQUESTS_PER_WINDOW = 120;

interface Bucket {
  windowStart: number;
  count: number;
}

const buckets = new Map<string, Bucket>();

export function allowRequest(clientKey: string, now = Date.now()): boolean {
  const bucket = buckets.get(clientKey);
  // Fixed windows (not sliding) are deliberate: the upstream API bills per
  // calendar minute, so matching its accounting avoids surprise 429s.
  if (!bucket || now - bucket.windowStart >= WINDOW_MS) {
    buckets.set(clientKey, { windowStart: now, count: 1 });
    return true;
  }
  if (bucket.count >= MAX_REQUESTS_PER_WINDOW) {
    return false;
  }
  bucket.count += 1;
  return true;
}

// Called from the hourly maintenance job; without it, keys for one-off
// clients would accumulate for the life of the process.
export function pruneIdleBuckets(now = Date.now()): number {
  let pruned = 0;
  for (const [clientKey, bucket] of buckets) {
    if (now - bucket.windowStart >= WINDOW_MS) {
      buckets.delete(clientKey);
      pruned += 1;
    }
  }
  return pruned;
}

