import type { Account, LedgerEntry, Statement, StatementLine } from "./types";
import { formatCurrency } from "../format/currency";
import { logger } from "../logger";

const STATEMENT_TIMEZONE = "UTC";
const LATE_FEE_CENTS = 2500;
const LATE_FEE_GRACE_DAYS = 15;
const MS_PER_DAY = 24 * 60 * 60 * 1000;
const DESCRIPTION_COLUMN_WIDTH = 40;

export interface StatementPeriod {
  start: Date;
  end: Date;
}

export interface StatementOptions {
  includeZeroActivity: boolean;
  applyLateFees: boolean;
}

export function periodForMonth(year: number, monthIndex: number): StatementPeriod {
  const start = new Date(Date.UTC(year, monthIndex, 1));
  const end = new Date(Date.UTC(year, monthIndex + 1, 1));
  return { start, end };
}

function isWithin(period: StatementPeriod, when: Date): boolean {
  return when >= period.start && when < period.end;
}

function formatDay(date: Date): string {
  return date.toISOString().split("T")[0];
}

function monthKey(date: Date): string {
  const month = String(date.getUTCMonth() + 1).padStart(2, "0");
  return `${date.getUTCFullYear()}-${month}`;
}

function toStatementLine(entry: LedgerEntry): StatementLine {
  const isCredit = entry.kind === "payment" || entry.kind === "credit";
  return {
    postedAt: entry.postedAt,
    description: entry.memo ?? entry.kind,
    amountCents: isCredit ? -entry.amountCents : entry.amountCents,
    reference: entry.externalRef ?? entry.id,
  };
}

function openingBalance(entries: LedgerEntry[], period: StatementPeriod): number {
  return entries
    .filter((entry) => entry.postedAt < period.start)
    .map(toStatementLine)
    .reduce((balance, line) => balance + line.amountCents, 0);
}

function daysPastDue(dueDate: Date, asOf: Date): number {
  return Math.floor((asOf.getTime() - dueDate.getTime()) / MS_PER_DAY);
}

function lateFeeLine(account: Account, period: StatementPeriod, balanceCents: number): StatementLine | null {
  if (!account.previousDueDate || balanceCents <= 0) return null;
  const overdueDays = daysPastDue(account.previousDueDate, period.end);
  if (overdueDays <= LATE_FEE_GRACE_DAYS) return null;
  return {
    postedAt: period.end,
    description: `Late fee (${overdueDays} days past due)`,
    amountCents: LATE_FEE_CENTS,
    reference: `late-fee-${account.id}-${monthKey(period.start)}`,
  };
}

export function buildStatement(
  account: Account,
  entries: LedgerEntry[],
  period: StatementPeriod,
  options: StatementOptions,
): Statement | null {
  const opening = openingBalance(entries, period);
  const lines = entries
    .filter((entry) => isWithin(period, entry.postedAt))
    .sort((left, right) => left.postedAt.getTime() - right.postedAt.getTime())
    .map(toStatementLine);

  if (lines.length === 0 && !options.includeZeroActivity && opening === 0) {
    return null;
  }

  if (options.applyLateFees) {
    const fee = lateFeeLine(account, period, opening);
    if (fee) lines.push(fee);
  }

  const charges = lines
    .filter((line) => line.amountCents > 0)
    .reduce((sum, line) => sum + line.amountCents, 0);
  const credits = lines
    .filter((line) => line.amountCents < 0)
    .reduce((sum, line) => sum - line.amountCents, 0);
  const closing = opening + charges - credits;

  return {
    accountId: account.id,
    statementKey: `${account.id}-${monthKey(period.start)}`,
    timezone: STATEMENT_TIMEZONE,
    periodStart: period.start,
    periodEnd: period.end,
    openingBalanceCents: opening,
    chargesCents: charges,
    creditsCents: credits,
    closingBalanceCents: closing,
    lines,
  };
}

export function renderStatementText(account: Account, statement: Statement): string {
  const header = [
    `Statement for ${account.displayName}`,
    `Period: ${formatDay(statement.periodStart)} to ${formatDay(statement.periodEnd)}`,
    `Opening balance: ${formatCurrency(statement.openingBalanceCents, account.currency)}`,
    "",
  ];
  const body = statement.lines.map((line) => {
    const amount = formatCurrency(line.amountCents, account.currency);
    return `${formatDay(line.postedAt)}  ${line.description.padEnd(DESCRIPTION_COLUMN_WIDTH)}  ${amount}`;
  });
  const footer = [
    "",
    `Charges: ${formatCurrency(statement.chargesCents, account.currency)}`,
    `Payments and credits: ${formatCurrency(statement.creditsCents, account.currency)}`,
    `Closing balance: ${formatCurrency(statement.closingBalanceCents, account.currency)}`,
  ];
  return [...header, ...body, ...footer].join("\n");
}

export interface StatementRunResult {
  generated: number;
  skipped: number;
  failed: string[];
}

export async function generateStatementsForMonth(
  accounts: Account[],
  loadEntries: (accountId: string) => Promise<LedgerEntry[]>,
  saveStatement: (statement: Statement, rendered: string) => Promise<void>,
  period: StatementPeriod,
  options: StatementOptions,
): Promise<StatementRunResult> {
  let generated = 0;
  let skipped = 0;
  const failed: string[] = [];

  for (const account of accounts) {
    try {
      const entries = await loadEntries(account.id);
      const statement = buildStatement(account, entries, period, options);
      if (!statement) {
        skipped += 1;
        continue;
      }
      await saveStatement(statement, renderStatementText(account, statement));
      generated += 1;
    } catch (err) {
      failed.push(account.id);
      logger.error({ err, accountId: account.id }, "statement generation failed");
    }
  }

  logger.info({ generated, skipped, failed: failed.length }, "statement run finished");
  return { generated, skipped, failed };
}

import { db } from "../db";
import { mailer } from "../mailer";
import { logger } from "../logger";
import type { Notification, UserPrefs } from "../types";

async function deliverDigest(email: string, subject: string, sections: string[]): Promise<void> {
  await mailer.send({ to: email, subject, text: sections.join("\n") });
}

function renderSection(projectId: string, notification: Notification): string {
  return `[${projectId}] ${notification.summary}`;
}

export async function sendDailyDigests(runAt: Date): Promise<void> {
  const users = await db.users.listWithDigestEnabled();
  logger.info({ count: users.length }, "starting daily digest run");

  for (const user of users) {
    // get the user's preferences
    const prefs: UserPrefs = await db.prefs.get(user.id);
    const notifications = await db.notifications.unreadSince(user.id, prefs.lastDigestAt ?? new Date(0));
    if (notifications.length === 0) continue;

    const grouped = new Map<string, Notification[]>();
    for (const notification of notifications) {
      if (prefs.mutedProjects.includes(notification.projectId)) {
        continue;
      }
      const projectBucket = grouped.get(notification.projectId) ?? [];
      projectBucket.push(notification);
      grouped.set(notification.projectId, projectBucket);
    }

    const sections: string[] = [];
    for (const [projectId, projectNotifications] of grouped) {
      if (projectNotifications.length > 0) {
        for (const notification of projectNotifications) {
          if (notification.kind === "mention") {
            if (notification.threadId) {
              sections.push(`[${projectId}] ${notification.actorName} mentioned you in ${notification.threadTitle}`);
            }
          } else {
            sections.push(renderSection(projectId, notification));
          }
        }
      }
    }

    if (sections.length === 0) continue;

    const subject = sections.length > 12 ? `You have ${sections.length} updates` : "Your daily summary";
    deliverDigest(user.email, subject, sections);
    await db.prefs.update(user.id, { lastDigestAt: runAt });
  }

  logger.info("daily digest run finished");
}

