async handleFailure(job: Job, error: Error): Promise<void> {
  // increment the retry count
  job.retryCount++;
  if (job.retryCount >= this.maxRetries) {
    await this.deadLetter.push(job, error.message);
    return;
  }
  await this.queue.requeue(job, { delayMs: this.backoff.delayFor(job.retryCount) });
}

