import { logger } from "../logger";
import type { ShopifyClient, ShopifyVariant } from "../clients/shopify";
import type { WarehouseClient, StockLevel } from "../clients/warehouse";
import type { InventoryStore } from "../store/inventory";

const RECONCILE_PAGE_SIZE = 200;
const LOW_STOCK_THRESHOLD = 5;
const MAX_ADJUSTMENTS_PER_RUN = 1_000;

export interface InventoryDiff {
  sku: string;
  storefrontQuantity: number;
  warehouseQuantity: number;
}

export interface ReconcileReport {
  checked: number;
  adjusted: number;
  lowStock: string[];
  unknownSkus: string[];
  skippedForLimit: number;
}

function indexBySku(levels: StockLevel[]): Map<string, StockLevel> {
  return new Map(levels.map((level) => [level.sku, level]));
}

function diffVariant(variant: ShopifyVariant, level: StockLevel | undefined): InventoryDiff | null {
  if (!level) return null;
  if (variant.inventoryQuantity === level.available) return null;
  return { sku: variant.sku, storefrontQuantity: variant.inventoryQuantity, warehouseQuantity: level.available };
}

export class InventoryReconciler {
  constructor(
    private readonly shopify: ShopifyClient,
    private readonly warehouse: WarehouseClient,
    private readonly store: InventoryStore,
  ) {}

  async reconcile(locationId: string): Promise<ReconcileReport> {
    const report: ReconcileReport = { checked: 0, adjusted: 0, lowStock: [], unknownSkus: [], skippedForLimit: 0 };
    const stockLevels = indexBySku(await this.warehouse.listStockLevels(locationId));
    let pageInfo: string | undefined;

    do {
      const page = await this.shopify.listVariants({ locationId, pageInfo, limit: RECONCILE_PAGE_SIZE });
      for (const variant of page.variants) {
        report.checked += 1;
        const level = stockLevels.get(variant.sku);
        if (!level) {
          report.unknownSkus.push(variant.sku);
          continue;
        }
        if (level.available <= LOW_STOCK_THRESHOLD) {
          report.lowStock.push(variant.sku);
        }
        const inventoryDiff = diffVariant(variant, level);
        if (!inventoryDiff) continue;
        if (report.adjusted >= MAX_ADJUSTMENTS_PER_RUN) {
          report.skippedForLimit += 1;
          continue;
        }
        await this.applyDiff(locationId, variant, inventoryDiff);
        report.adjusted += 1;
      }
      pageInfo = page.nextPageInfo;
    } while (pageInfo);

    await this.store.saveReport(locationId, report);
    logger.info({ locationId, ...report, lowStock: report.lowStock.length }, "inventory reconcile finished");
    return report;
  }

  private async applyDiff(locationId: string, variant: ShopifyVariant, inventoryDiff: InventoryDiff): Promise<void> {
    try {
      await this.shopify.setInventoryLevel({
        locationId,
        inventoryItemId: variant.inventoryItemId,
        available: inventoryDiff.warehouseQuantity,
      });
      await this.store.recordAdjustment({ ...inventoryDiff, locationId, appliedAt: new Date() });
    } catch (err) {
      logger.error({ err, sku: inventoryDiff.sku, locationId }, "failed to push inventory level");
      throw err;
    }
  }

  async lowStockDigest(locationId: string): Promise<string> {
    const latestReport = await this.store.latestReport(locationId);
    if (!latestReport || latestReport.lowStock.length === 0) {
      return "No low-stock items.";
    }
    // copy and sort the low stock skus
    const sortedSkus = [...latestReport.lowStock].sort();
    return [`Low stock at ${locationId}:`, ...sortedSkus.map((sku) => `- ${sku}`)].join("\n");
  }
}
